def _published_document_id(doc_type: str, repo_path: str | None) -> str | None:
    """Mirror the docs site's ``documentId(entry)`` for published sources."""
    if not repo_path:
        return None
    normalized = str(repo_path).strip().replace("\\", "/")
    if (
        not normalized
        or normalized.startswith("/")
        or ":" in normalized
        or "//" in normalized
    ):
        return None
    path = PurePosixPath(normalized)
    if any(part in {"", ".", ".."} for part in path.parts):
        return None
    if path.suffix.casefold() not in {".md", ".mdx"}:
        return None
    if path.name.startswith("_"):
        return None

    expected_folder = _DOC_TYPE_FOLDER.get((doc_type or "").upper())
    if not expected_folder or path.parts[0] != expected_folder:
        return None

    without_suffix = str(path.with_suffix(""))
    # Exact mirror of site/src/content.config.ts: preserve path/case and only
    # replace underscores in each path component.
    return "/".join(part.replace("_", "-") for part in without_suffix.split("/"))
